<section class="panel"><div class="panel-heading"><div><h2>Installed modules</h2><p>Dependencies are validated before enabling or disabling a module. Review each proposed change before applying.</p></div><span class="pill"><?= count($modules) ?> REGISTERED</span></div><div class="module-grid"><?php foreach($modules as $name=>$info): $enabled=$manager->enabled($name);$required=($info['required']??false)===true; ?><article class="module-card"><div class="module-head"><span class="module-icon"><?= esc(strtoupper(substr($name,0,1))) ?></span><span class="pill <?= $enabled?'pill-green':'' ?>"><?= $enabled?'ACTIVE':'DISABLED' ?></span></div><h3><?= esc($name) ?></h3><p><?= esc($info['description']??'') ?></p><p class="hint">Requires: <?= esc(implode(', ',array_map(static fn($k,$v)=>$k.' '.$v,array_keys($info['dependencies']??[]),array_values($info['dependencies']??[]))) ?: 'None') ?></p><div class="module-foot"><small>VERSION <?= esc($info['version']??'0.0.0') ?></small><?php if($required):?><span class="muted">REQUIRED MODULE</span><?php else:?><a class="btn btn-small <?= $enabled?'btn-secondary':'btn-primary' ?>" href="/admin/modules/plan?name=<?= rawurlencode($name) ?>&amp;enabled=<?= $enabled?'0':'1' ?>"><?= $enabled?'Review deactivation':'Review activation' ?></a><?php endif; ?></div></article><?php endforeach; ?></div><p class="hint">Signed module installation remains CLI-only. Module state changes do not reverse database migrations or reload already-running processes.</p></section>
